1	package mevwatch
2	
3	import (
4		"bufio"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"math"
10		"os"
11		"path/filepath"
12		"sort"
13		"strings"
14		"syscall"
15	)
16	
17	// Block is one validated, deduplicated input block. Swaps are kept in
18	// canonical order: exact duplicates removed, sorted by Index.
19	type Block struct {
20		ChainID     string
21		BlockHash   string
22		BlockNumber int64
23		Swaps       []Swap
24	}
25	
26	// ReportFinding is one risk conclusion inside a block report. Evidence
27	// carries the raw fields of every swap that participated in the judgment.
28	type ReportFinding struct {
29		Kind     string `json:"kind"`
30		Severity int    `json:"severity"`
31		TxHash   string `json:"txHash"`
32		Evidence []Swap `json:"evidence"`
33	}
34	
35	// Report is the archived per-block risk report.
36	type Report struct {
37		ChainID     string          `json:"chainId"`
38		BlockHash   string          `json:"blockHash"`
39		BlockNumber int64           `json:"blockNumber"`
40		SwapCount   int             `json:"swapCount"`
41		Findings    []ReportFinding `json:"findings"`
42	}
43	
44	// LineError pins a replay failure to a 1-based input line.
45	type LineError struct {
46		Line int
47		Err  error
48	}
49	
50	func (e *LineError) Error() string { return fmt.Sprintf("line %d: %v", e.Line, e.Err) }
51	func (e *LineError) Unwrap() error { return e.Err }
52	
53	// ErrBusy reports an archive locked by another process.
54	var ErrBusy = errors.New("archive is busy")
55	
56	// ErrUnknownBlock reports a query for a block that was never archived.
57	var ErrUnknownBlock = errors.New("unknown block")
58	
59	type blockID struct {
60		chainID   string
61		blockHash string
62	}
63	
64	// blockLine mirrors one input line. Pointers distinguish a missing field
65	// from an explicit zero value.
66	type blockLine struct {
67		ChainID     *string `json:"chainId"`
68		BlockHash   *string `json:"blockHash"`
69		BlockNumber *int64  `json:"blockNumber"`
70		Swaps       *[]Swap `json:"swaps"`
71	}
72	
73	func parseBlock(text string) (Block, error) {
74		var raw blockLine
75		dec := json.NewDecoder(strings.NewReader(text))
76		if err := dec.Decode(&raw); err != nil {
77			return Block{}, fmt.Errorf("invalid JSON: %w", err)
78		}
79		if dec.More() {
80			return Block{}, errors.New("invalid JSON: unexpected trailing data")
81		}
82		if raw.ChainID == nil || *raw.ChainID == "" {
83			return Block{}, errors.New("chainId must be a non-empty string")
84		}
85		if raw.BlockHash == nil || *raw.BlockHash == "" {
86			return Block{}, errors.New("blockHash must be a non-empty string")
87		}
88		if raw.BlockNumber == nil {
89			return Block{}, errors.New("blockNumber is required")
90		}
91		if *raw.BlockNumber < 0 {
92			return Block{}, fmt.Errorf("blockNumber must be non-negative, got %d", *raw.BlockNumber)
93		}
94		if raw.Swaps == nil {
95			return Block{}, errors.New("swaps must be an array")
96		}
97	
98		byTx := make(map[string]Swap)
99		byIndex := make(map[int]string)
100		swaps := []Swap{}
101		for i, s := range *raw.Swaps {
102			if s.TxHash == "" {
103				return Block{}, fmt.Errorf("swaps[%d]: TxHash must not be empty", i)
104			}
105			if s.Pool == "" {
106				return Block{}, fmt.Errorf("swaps[%d]: Pool must not be empty", i)
107			}
108			if s.Trader == "" {
109				return Block{}, fmt.Errorf("swaps[%d]: Trader must not be empty", i)
110			}
111			if s.In < 0 || s.Out < 0 || s.GasPrice < 0 || s.Index < 0 {
112				return Block{}, fmt.Errorf("swaps[%d]: In, Out, GasPrice and Index must be non-negative", i)
113			}
114			if prev, ok := byTx[s.TxHash]; ok {
115				if prev != s {
116					return Block{}, fmt.Errorf("swaps[%d]: conflicting records for tx %s", i, s.TxHash)
117				}
118				continue // exact duplicate, keep one copy
119			}
120			if other, ok := byIndex[s.Index]; ok {
121				return Block{}, fmt.Errorf("swaps[%d]: Index %d already used by tx %s", i, s.Index, other)
122			}
123			byTx[s.TxHash] = s
124			byIndex[s.Index] = s.TxHash
125			swaps = append(swaps, s)
126		}
127		sort.Slice(swaps, func(i, j int) bool { return swaps[i].Index < swaps[j].Index })
128		return Block{
129			ChainID:     *raw.ChainID,
130			BlockHash:   *raw.BlockHash,
131			BlockNumber: *raw.BlockNumber,
132			Swaps:       swaps,
133		}, nil
134	}
135	
136	func swapsEqual(a, b []Swap) bool {
137		if len(a) != len(b) {
138			return false
139		}
140		for i := range a {
141			if a[i] != b[i] {
142				return false
143			}
144		}
145		return true
146	}
147	
148	// sameContent reports whether two blocks carry the same content. Both sides
149	// are canonical (deduplicated, sorted by Index), so ordering and exact
150	// duplicates in the input do not affect the comparison.
151	func sameContent(blockNumber int64, swaps []Swap, b Block) bool {
152		return blockNumber == b.BlockNumber && swapsEqual(swaps, b.Swaps)
153	}
154	
155	// gasDominates reports whether front strictly exceeds twice victim,
156	// staying correct when victim is zero or math.MaxInt64.
157	func gasDominates(front, victim int64) bool {
158		return victim <= math.MaxInt64/2 && front > victim*2
159	}
160	
161	// DetectBlock checks every swap against its adjacent neighbours within its
162	// pool: a sandwich when the same trader brackets the victim with higher gas
163	// on both sides, otherwise a displacement when the previous swap's gas
164	// strictly doubles the victim's. The last swap of a pool is checked too.
165	func DetectBlock(swaps []Swap) []ReportFinding {
166		pools := make(map[string][]Swap)
167		for _, s := range swaps {
168			pools[s.Pool] = append(pools[s.Pool], s)
169		}
170		findings := []ReportFinding{}
171		for _, pool := range pools {
172			sort.Slice(pool, func(i, j int) bool { return pool[i].Index < pool[j].Index })
173			for i, victim := range pool {
174				var front, back *Swap
175				if i > 0 {
176					front = &pool[i-1]
177				}
178				if i+1 < len(pool) {
179					back = &pool[i+1]
180				}
181				switch {
182				case front != nil && back != nil &&
183					front.Trader == back.Trader && front.Trader != victim.Trader &&
184					front.GasPrice > victim.GasPrice && back.GasPrice > victim.GasPrice:
185					findings = append(findings, ReportFinding{
186						Kind: "sandwich", Severity: 3, TxHash: victim.TxHash,
187						Evidence: []Swap{*front, victim, *back},
188					})
189				case front != nil && gasDominates(front.GasPrice, victim.GasPrice):
190					findings = append(findings, ReportFinding{
191						Kind: "displacement", Severity: 2, TxHash: victim.TxHash,
192						Evidence: []Swap{*front, victim},
193					})
194				}
195			}
196		}
197		sort.Slice(findings, func(i, j int) bool {
198			if findings[i].Severity != findings[j].Severity {
199				return findings[i].Severity > findings[j].Severity
200			}
201			return findings[i].TxHash < findings[j].TxHash
202		})
203		return findings
204	}
205	
206	// record is the archived form of a block: the report plus the canonical
207	// swaps, so a later import can detect content conflicts.
208	type record struct {
209		ChainID     string          `json:"chainId"`
210		BlockHash   string          `json:"blockHash"`
211		BlockNumber int64           `json:"blockNumber"`
212		Swaps       []Swap          `json:"swaps"`
213		Findings    []ReportFinding `json:"findings"`
214	}
215	
216	func (r record) id() blockID { return blockID{r.ChainID, r.BlockHash} }
217	
218	func (r record) report() Report {
219		return Report{
220			ChainID:     r.ChainID,
221			BlockHash:   r.BlockHash,
222			BlockNumber: r.BlockNumber,
223			SwapCount:   len(r.Swaps),
224			Findings:    r.Findings,
225		}
226	}
227	
228	const (
229		archiveFileName = "archive.json"
230		lockFileName    = "lock"
231	)
232	
233	type archiveData struct {
234		Records []record `json:"records"`
235	}
236	
237	func readArchive(dir string) (archiveData, error) {
238		raw, err := os.ReadFile(filepath.Join(dir, archiveFileName))
239		if errors.Is(err, os.ErrNotExist) {
240			return archiveData{Records: []record{}}, nil
241		}
242		if err != nil {
243			return archiveData{}, err
244		}
245		var data archiveData
246		if err := json.Unmarshal(raw, &data); err != nil {
247			return archiveData{}, fmt.Errorf("archive is corrupted: %w", err)
248		}
249		return data, nil
250	}
251	
252	// writeArchiveAtomic replaces the archive file in one rename, so a crash
253	// can only expose the previous or the next complete commit, never a half
254	// written file.
255	func writeArchiveAtomic(dir string, data archiveData) error {
256		raw, err := json.MarshalIndent(data, "", "  ")
257		if err != nil {
258			return err
259		}
260		tmp := filepath.Join(dir, archiveFileName+".tmp")
261		f, err := os.OpenFile(tmp, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0o644)
262		if err != nil {
263			return err
264		}
265		if _, err := f.Write(raw); err != nil {
266			f.Close()
267			os.Remove(tmp)
268			return err
269		}
270		if err := f.Sync(); err != nil {
271			f.Close()
272			os.Remove(tmp)
273			return err
274		}
275		if err := f.Close(); err != nil {
276			os.Remove(tmp)
277			return err
278		}
279		if err := os.Rename(tmp, filepath.Join(dir, archiveFileName)); err != nil {
280			os.Remove(tmp)
281			return err
282		}
283		if d, err := os.Open(dir); err == nil {
284			d.Sync()
285			d.Close()
286		}
287		return nil
288	}
289	
290	// lockArchive takes an flock on the archive's lock file. The lock is
291	// released automatically if the process dies, so no stale locks survive.
292	func lockArchive(dir string, how int) (*os.File, error) {
293		f, err := os.OpenFile(filepath.Join(dir, lockFileName), os.O_CREATE|os.O_RDWR, 0o644)
294		if err != nil {
295			return nil, err
296		}
297		if err := syscall.Flock(int(f.Fd()), how); err != nil {
298			f.Close()
299			if errors.Is(err, syscall.EWOULDBLOCK) {
300				return nil, ErrBusy
301			}
302			return nil, err
303		}
304		return f, nil
305	}
306	
307	type parsedBlock struct {
308		line  int
309		block Block
310	}
311	
312	func parseBlocks(r io.Reader) ([]parsedBlock, error) {
313		var out []parsedBlock
314		reader := bufio.NewReader(r)
315		lineNo := 0
316		for {
317			raw, err := reader.ReadBytes('\n')
318			if len(raw) > 0 {
319				lineNo++
320			}
321			if text := strings.TrimSpace(string(raw)); text != "" {
322				block, perr := parseBlock(text)
323				if perr != nil {
324					return nil, &LineError{Line: lineNo, Err: perr}
325				}
326				out = append(out, parsedBlock{line: lineNo, block: block})
327			}
328			if err == io.EOF {
329				return out, nil
330			}
331			if err != nil {
332				return nil, err
333			}
334		}
335	}
336	
337	// ReplayFile imports the line-delimited blocks in inputPath into the
338	// archive at dir and returns one report per distinct block, in order of
339	// first appearance.
340	func ReplayFile(inputPath, dir string) ([]Report, error) {
341		f, err := os.Open(inputPath)
342		if err != nil {
343			return nil, err
344		}
345		defer f.Close()
346		return Replay(f, dir)
347	}
348	
349	// Replay parses, validates and archives blocks from r. Every line is
350	// checked before anything is written; any failure leaves the archive
351	// untouched. New reports are committed together in a single atomic write.
352	func Replay(input io.Reader, dir string) ([]Report, error) {
353		parsed, err := parseBlocks(input)
354		if err != nil {
355			return nil, err
356		}
357	
358		// Collapse repeated identities within this file, keeping first
359		// appearance order; conflicting content rejects the whole file.
360		type occurrence struct {
361			block Block
362			line  int
363		}
364		order := []occurrence{}
365		firstSeen := make(map[blockID]int)
366		for _, p := range parsed {
367			id := blockID{p.block.ChainID, p.block.BlockHash}
368			if first, ok := firstSeen[id]; ok {
369				if !sameContent(order[first].block.BlockNumber, order[first].block.Swaps, p.block) {
370					return nil, &LineError{Line: p.line, Err: fmt.Errorf(
371						"block %s/%s conflicts with line %d", id.chainID, id.blockHash, order[first].line)}
372				}
373				continue
374			}
375			firstSeen[id] = len(order)
376			order = append(order, occurrence{block: p.block, line: p.line})
377		}
378	
379		if err := os.MkdirAll(dir, 0o755); err != nil {
380			return nil, err
381		}
382		lock, err := lockArchive(dir, syscall.LOCK_EX|syscall.LOCK_NB)
383		if err != nil {
384			return nil, err
385		}
386		defer lock.Close()
387	
388		data, err := readArchive(dir)
389		if err != nil {
390			return nil, err
391		}
392		archived := make(map[blockID]int, len(data.Records))
393		for i, rec := range data.Records {
394			archived[rec.id()] = i
395		}
396	
397		reports := make([]Report, 0, len(order))
398		changed := false
399		for _, occ := range order {
400			id := blockID{occ.block.ChainID, occ.block.BlockHash}
401			if idx, ok := archived[id]; ok {
402				rec := data.Records[idx]
403				if !sameContent(rec.BlockNumber, rec.Swaps, occ.block) {
404					return nil, &LineError{Line: occ.line, Err: fmt.Errorf(
405						"block %s/%s conflicts with the archived record", id.chainID, id.blockHash)}
406				}
407				// Identical re-import: return the original report, add nothing.
408				reports = append(reports, rec.report())
409				continue
410			}
411			rec := record{
412				ChainID:     occ.block.ChainID,
413				BlockHash:   occ.block.BlockHash,
414				BlockNumber: occ.block.BlockNumber,
415				Swaps:       occ.block.Swaps,
416				Findings:    DetectBlock(occ.block.Swaps),
417			}
418			archived[id] = len(data.Records)
419			data.Records = append(data.Records, rec)
420			reports = append(reports, rec.report())
421			changed = true
422		}
423		if changed {
424			if err := writeArchiveAtomic(dir, data); err != nil {
425				return nil, err
426			}
427		}
428		return reports, nil
429	}
430	
431	// Query returns the archived report for one block identity. It only reads
432	// the archive; the original input file is not needed.
433	func Query(dir, chainID, blockHash string) (Report, error) {
434		if _, err := os.Stat(dir); err != nil {
435			if errors.Is(err, os.ErrNotExist) {
436				return Report{}, ErrUnknownBlock
437			}
438			return Report{}, err
439		}
440		lock, err := lockArchive(dir, syscall.LOCK_SH)
441		if err != nil {
442			return Report{}, err
443		}
444		defer lock.Close()
445	
446		data, err := readArchive(dir)
447		if err != nil {
448			return Report{}, err
449		}
450		for _, rec := range data.Records {
451			if rec.ChainID == chainID && rec.BlockHash == blockHash {
452				return rec.report(), nil
453			}
454		}
455		return Report{}, ErrUnknownBlock
456	}
